{S('dark',f'''{head('O funil','Cada etapa pensada para levar a paciente até a cadeira')}<div class="g g4" style="grid-template-columns:repeat(5,1fr)"><div class="c"><b>1</b><h3>Atração</h3><p>Conteúdo 3x/semana + anúncio local para Goiânia</p></div><div class="c"><b>2</b><h3>Conversão</h3><p>Landing Page e link da bio levam ao WhatsApp</p></div><div class="c"><b>3</b><h3>Qualificação</h3><p>3 perguntas antes da conversa: queixa, prazo, histórico</p></div><div class="c"><b>4</b><h3>Fechamento</h3><p>Avaliação com planejamento, parcelamento e follow-up 24h/7 dias</p></div><div class="c"><b>5</b><h3>Prova social</h3><p>Depoimentos e avaliações no Google alimentam o topo</p></div></div><p style="margin-top:30px;font-size:19px;color:#e2bf75">CTA único e padrão: "Agende sua avaliação pelo WhatsApp".</p><div class="foot"><span>EXPOENTE</span><span>06</span></div>''')}
